<?php namespace Workspace;
$base=['project'=>$project,'kind'=>$kind]+($target?['target'=>$target]:[]);
$selected=$source?['source'=>$source['id']]:[];
function forumHidden(array $params):void{foreach($params as $key=>$value)if($value!==null)echo '<input type="hidden" name="',h($key),'" value="',h($value),'">';}
?>
<section class="panel"><h2>Обсуждения проекта</h2><p>Содержимое читается непосредственно из Forum. Права проекта не заменяют ACL форума; для каждого пользователя нужен отдельный токен. Forum Edition <?= h(FORUM_EDITION) ?> · Engine <?= h(FORUM_CORE) ?>.</p>
<form method="get" class="inline"><input type="hidden" name="p" value="forum"><label>Проект<select name="project" required><option value="">Выберите</option><?php selectOptions($projects,$project) ?></select></label><button>Открыть</button></form>
<?php if($project!==null): ?><p><a href="<?= h(url('project',['id'=>$project])) ?>">← Проект</a> · <a href="<?= h(url('forum',$base)) ?>">Разделы форума</a><?php if($target): ?> · <?= $kind==='task'?'Задача':'Выпуск' ?> #<?= (int)$target ?><?php endif ?></p><?php endif ?></section>
<?php if($error): ?><p class="panel planning-warning"><?= h($error) ?></p><?php endif ?>
<?php if($project!==null&&!$source): ?><section class="panel"><h2>Доступные разделы</h2><?php if(!$sources): ?><p>На этой странице нет доступных привязок. Проверьте индивидуальную учётную запись и права Forum.</p><?php endif ?>
<?php foreach($sources as $s): ?><div class="splitrow"><?php if((int)$s['active']): ?><a href="<?= h(url('forum',$base+['source'=>$s['id']])) ?>"><?= h($s['name']) ?></a><?php else: ?><span><?= h($s['name']) ?></span><?php endif ?><?php if($user['role']==='owner'): ?><form method="post"><?php formFields('forum.toggle');forumHidden(['project_id'=>$project,'source_id'=>$s['id'],'active'=>(int)$s['active']?0:1]); ?><button class="secondary"><?= (int)$s['active']?'Отключить':'Включить' ?></button></form><?php endif ?></div><?php endforeach ?>
<p><?php if($offset>1): ?><a href="<?= h(url('forum',$base+['bindings_page'=>$offset-1])) ?>">Предыдущая</a> · <?php endif ?><?php if($offset<100): ?><a href="<?= h(url('forum',$base+['bindings_page'=>$offset+1])) ?>">Следующая</a><?php endif ?></p></section>
<?php if($available&&$user['role']==='owner'): ?><section class="panel"><h2>Привязать раздел</h2><p>UUID берётся из адреса раздела Forum. Доступ проверяется на сервере.</p><form method="post"><?php formFields('forum.bind');forumHidden(['project_id'=>$project]); ?><label>Подключение<select name="connection"><?php selectOptions($available) ?></select></label><label>UUID раздела<input name="board" required maxlength="36"></label><button class="primary">Привязать (MFA)</button></form></section><?php endif ?><?php endif ?>
<?php if($source&&$board): $params=['project_id'=>$project,'source_id'=>$source['id']];$perms=$board['permissions']; ?><section class="panel"><h2><?= h($board['name']??'Раздел') ?></h2><p><a rel="noreferrer" href="<?= h($source['origin'].'/forum/boards/'.forumId($board['id'])) ?>">Открыть в Forum</a></p>
<?php if(!$detail&&!$pending): ?><form method="get" class="inline"><?php forumHidden(['p'=>'forum']+$base+$selected); ?><label>Поиск связанных тем в этом разделе<input name="q" value="<?= h($term) ?>" maxlength="100" minlength="2"></label><button>Найти</button></form>
<?php if(!$rows): ?><p>Нет связанных тем на этой странице.</p><?php endif ?><?php foreach($rows as $row): ?><p><a href="<?= h(url('forum',$base+$selected+['topic'=>$row['local']['id']])) ?>"><?= h($row['title']) ?></a> · <?= $row['local']['task_id']?'Задача #'.(int)$row['local']['task_id']:'Выпуск #'.(int)$row['local']['release_id'] ?><?= $row['locked']?' · Закрыта':'' ?><?= $row['pinned']?' · Закреплена':'' ?></p><?php endforeach ?>
<?php foreach($ownPending as $item): ?><p><a href="<?= h(url('forum',$base+$selected+['topic'=>$item['id']])) ?>">Мой запрос #<?= (int)$item['id'] ?> — <?= h($item['state']) ?></a></p><?php endforeach ?>
<?php endif ?></section>
<?php if($detail): $thread=$detail['thread'];$topic=(int)$detail['local_id'];$params+=['topic_id'=>$topic,'page'=>$n]; ?><section class="panel"><h2><?= h($thread['title']) ?></h2><p><?php if($detail['task_id']): ?><a href="<?= h(url('task',['id'=>$detail['task_id']])) ?>">Задача #<?= (int)$detail['task_id'] ?></a><?php else: ?><a href="<?= h(url('releases',['project'=>$project,'id'=>$detail['release_id']])) ?>">Выпуск #<?= (int)$detail['release_id'] ?></a><?php endif ?> · <a rel="noreferrer" href="<?= h($source['origin'].'/forum/threads/'.forumId($thread['id'])) ?>">Тема в Forum</a> · <?= !empty($thread['locked'])?'Закрыта':'Открыта' ?><?= !empty($thread['pinned'])?' · Закреплена':'' ?></p>
<h3>Участники текущей страницы</h3><p><?= h(implode(', ',array_values($participants))) ?: 'Нет видимых профилей.' ?></p>
<?php foreach($detail['posts'] as $post): if(!empty($post['ignored_author']))continue; ?><article class="panel inset"><strong><?= h(!empty($post['author_profile_visible'])?($post['author']??'Участник'):'Участник') ?></strong> <small><?= h($post['created_at']??'') ?></small><pre class="release-text"><?= h($post['body']??'') ?></pre>
<?php if($work&&($perms['report:create']??false)): ?><form method="post" class="inline"><?php formFields('forum.action');forumHidden($params+['operation'=>'report','post_id'=>$post['id']]); ?><label>Причина жалобы<input name="reason" minlength="3" maxlength="500" required></label><button class="secondary">Пожаловаться</button></form><?php endif ?></article><?php endforeach ?>
<?php if($work&&($perms['post:reply']??false)&&empty($thread['locked'])): ?><form method="post"><?php formFields('forum.action');forumHidden($params+['operation'=>'reply']); ?><label>Ответ (plain text)<textarea name="body" rows="5" maxlength="10000" required></textarea></label><button class="primary">Отправить в Forum (MFA)</button></form><?php endif ?>
<?php $buttons=[];if($manage&&($perms['thread:moderate']??false)){$buttons[empty($thread['locked'])?'lock':'unlock']=empty($thread['locked'])?'Закрыть':'Открыть';$buttons[empty($thread['pinned'])?'pin':'unpin']=empty($thread['pinned'])?'Закрепить':'Открепить';}if($work&&($perms['watch:use']??false))$buttons[empty($thread['watch_mode'])?'watch':'unwatch']=empty($thread['watch_mode'])?'Подписаться':'Отписаться';foreach($buttons as $op=>$label): ?><form method="post" class="inline"><?php formFields('forum.action');forumHidden($params+['operation'=>$op]); ?><button class="secondary"><?= h($label) ?> (MFA)</button></form><?php endforeach ?>
<?php if($operations): ?><h3>Мои операции</h3><?php foreach($operations as $o): ?><p><?= h($o['operation']) ?> · <?= h($o['state']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$o['created_at'])) ?> UTC</p><?php endforeach ?><p>При неопределённом результате не повторяйте отправку до проверки в Forum.</p><?php endif ?></section>
<?php elseif($pending): ?><section class="panel"><h2>Запрос #<?= (int)$pending['id'] ?> — <?= h($pending['state']) ?></h2><p>Ожидающая модерации заявка не является опубликованной темой. При потере ответа не создавайте дубликат.</p><?php if($manage&&in_array($pending['state'],['pending','sending'],true)): ?><form method="post"><?php formFields('forum.reconcile');forumHidden($params+['topic_id'=>$pending['id']]); ?><button>Сверить с Forum (MFA)</button></form><?php endif ?><?php if($manage&&in_array($pending['state'],['uncertain','rejected'],true)): ?><form method="post"><?php formFields('forum.attach');forumHidden($params+['kind'=>$pending['task_id']?'task':'release','target'=>$pending['task_id']??$pending['release_id']]); ?><label>Найдите тему в Forum и укажите её UUID<input name="thread" required maxlength="36"></label><button>Связать найденную тему (MFA)</button></form><?php endif ?></section>
<?php elseif($manage): ?><section class="panel"><h2>Связать существующую тему</h2><form method="post"><?php formFields('forum.attach');forumHidden($params); ?><label>Тип<select name="kind"><?php selectOptions(['task'=>'Задача','release'=>'Подтверждённый выпуск'],$kind) ?></select></label><label>ID карточки<input name="target" type="number" min="1" value="<?= h($target) ?>" required></label><label>UUID темы<input name="thread" maxlength="36" required></label><button>Связать (MFA)</button></form></section>
<?php if($perms['thread:create']??false): ?><section class="panel"><h2>Создать тему</h2><p>Текст отправляется в выбранный раздел. Не включайте закрытые сведения, если раздел публичный. Содержимое задачи или релиза не передаётся автоматически.</p><form method="post"><?php formFields('forum.create');forumHidden($params); ?><label>Тип<select name="kind"><?php selectOptions(['task'=>'Задача','release'=>'Подтверждённый выпуск'],$kind) ?></select></label><label>ID карточки<input name="target" type="number" min="1" value="<?= h($target) ?>" required></label><label>Заголовок<input name="title" required minlength="3" maxlength="180"></label><label>Текст<textarea name="body" required maxlength="10000" rows="6"></textarea></label><button class="primary">Отправить в Forum (MFA)</button></form></section><?php endif ?><?php endif ?>
<?php if(!$pending): ?><p><?php $nav=$base+$selected+($detail?['topic'=>$detail['local_id']]:[])+['q'=>$term];if($n>1): ?><a href="<?= h(url('forum',$nav+['n'=>$n-1])) ?>">Предыдущая</a> · <?php endif ?>Страница <?= $n ?><?php if($n<100): ?> · <a href="<?= h(url('forum',$nav+['n'=>$n+1])) ?>">Следующая</a><?php endif ?></p><?php endif ?><?php endif ?>
